'use strict';
const fs=require('node:fs'),path=require('node:path');
const root=path.resolve(__dirname,'..');
const file=rel=>path.join(root,rel);
function replaceRequired(text,from,to,label){if(!text.includes(from))throw Error('Missing patch marker: '+label);return text.replace(from,to);}
function insertBefore(text,marker,addition,label){if(!text.includes(marker))throw Error('Missing insert marker: '+label);return text.replace(marker,addition+marker);}
function replaceBetween(text,start,end,replacement,label){const a=text.indexOf(start),b=text.indexOf(end,a+start.length);if(a<0||b<0)throw Error('Missing range marker: '+label);return text.slice(0,a)+replacement+text.slice(b);}

